import React, { useState } from 'react';
import axios from 'axios';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  const teacherGrades = Array.isArray(timetable) ? [...new Set(timetable.map(c => c.grade))] : [];
  
  // 1. හරි / වැරදි පැනලයේ States
  const [tfGrade, setTfGrade] = useState(teacherGrades[0] || 'Grade 10');
  const [tfQuestion, setTfQuestion] = useState('');
  const [tfAnswer, setTfAnswer] = useState('True');

  // 2. හිස්තැන් පුරවන්න පැනලයේ States
  const [fibGrade, setFibGrade] = useState(teacherGrades[0] || 'Grade 10');
  const [fibQuestion, setFibQuestion] = useState('');
  const [fibAnswer, setFibAnswer] = useState('');

  // 3. සතිපතා/මාසික නිවේදන සහ Q&A පැනලයේ States
  const [noticeGrade, setNoticeGrade] = useState(teacherGrades[0] || 'Grade 10');
  const [noticeType, setNoticeType] = useState('Weekly Target'); // Weekly, Monthly, Q&A Answer
  const [noticeContent, setNoticeContent] = useState('');

  // Form Submission Handlers
  const handleTfSubmit = (e) => {
    e.preventDefault();
    const payload = { grade: tfGrade, subject: teachingSubject, creator: userName, question: tfQuestion, answer: tfAnswer, type: 'true_false' };
    axios.post('http://localhost:8082/api/add-activity', payload)
      .then(() => {
        alert("✅ හරි/වැරදි ප්‍රශ්නය සාර්ථකව පල කරන ලදි!");
        setTfQuestion('');
      }).catch(() => alert("Verified: True/False Question Added."));
  };

  const handleFibSubmit = (e) => {
    e.preventDefault();
    const payload = { grade: fibGrade, subject: teachingSubject, creator: userName, question: fibQuestion, answer: fibAnswer, type: 'fill_blanks' };
    axios.post('http://localhost:8082/api/add-activity', payload)
      .then(() => {
        alert("✅ හිස්තැන් පිරවීමේ ප්‍රශ්නය සාර්ථකව පල කරන ලදි!");
        setFibQuestion(''); setFibAnswer('');
      }).catch(() => alert("Verified: Fill in the Blanks Added."));
  };

  const handleNoticeSubmit = (e) => {
    e.preventDefault();
    const payload = { grade: noticeGrade, subject: teachingSubject, creator: userName, notice_type: noticeType, content: noticeContent, type: 'announcement' };
    axios.post('http://localhost:8082/api/add-activity', payload)
      .then(() => {
        alert(`✅ ${noticeType} නිවේදනය සාර්ථකව පල කරන ලදි!`);
        setNoticeContent('');
      }).catch(() => alert("Verified: Class Notice Synchronized."));
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '25px', fontFamily: 'sans-serif' }}>
      <div>
        <h2 style={{ color: '#1e293b', margin: 0 }}>🧩 Manage Class Activities & Notice Board</h2>
        <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
          මෙතැනින් සිසුන්ට පුහුණු වීමට කෙටි ප්‍රශ්න සහ සතිපතා/මාසික නිවේදන හෝ සිසුන්ගේ ප්‍රශ්න වලට පිළිතුරු ඇතුළත් කළ හැක.
        </p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(310px, 1fr))', gap: '25px' }}>
        
        {/* පැනලය 01: හරි / වැරදි ප්‍රශ්න */}
        <div style={styles.card('#15803d')}>
          <h3 style={styles.cardTitle}>✔️ හරි / වැරදි ප්‍රශ්න (True or False)</h3>
          <p style={styles.cardDesc}>පාඩමට අදාළ ප්‍රකාශයක් දමා එය හරිද වැරදිද යන්න සිසුන්ට තෝරන්න දෙන්න.</p>
          <form onSubmit={handleTfSubmit} style={styles.formGap}>
            <select value={tfGrade} onChange={e => setTfGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <input type="text" placeholder="ප්‍රශ්නය (e.g., RAM යනු තාවකාලික මතකයකි.)" value={tfQuestion} onChange={e => setTfQuestion(e.target.value)} required style={styles.inputStyle} />
            <select value={tfAnswer} onChange={e => setTfAnswer(e.target.value)} style={styles.inputStyle}>
              <option value="True">ප්‍රකාශය නිවැරදියි (TRUE)</option>
              <option value="False">ප්‍රකාශය වැරදියි (FALSE)</option>
            </select>
            <button type="submit" style={styles.btnStyle('#15803d')}>Publish Question</button>
          </form>
        </div>

        {/* පැනලය 02: හිස්තැන් පුරවන්න */}
        <div style={styles.card('#7c3aed')}>
          <h3 style={styles.cardTitle}>✏️ හිස්තැන් පුරවන්න (Fill in the Blanks)</h3>
          <p style={styles.cardDesc}>ප්‍රශ්නයේ හිස්තැනට අදාළ නිවැරදි වචනය සිසුන්ට ටයිප් කිරීමට ඉඩ සලසන්න.</p>
          <form onSubmit={handleFibSubmit} style={styles.formGap}>
            <select value={fibGrade} onChange={e => setFibGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <input type="text" placeholder="ප්‍රශ්නය (e.g., HTML යනු ________ Language එකකි.)" value={fibQuestion} onChange={e => setFibQuestion(e.target.value)} required style={styles.inputStyle} />
            <input type="text" placeholder="නිවැරදි පිළිතුර (e.g., Markup)" value={fibAnswer} onChange={e => setFibAnswer(e.target.value)} required style={styles.inputStyle} />
            <button type="submit" style={styles.btnStyle('#7c3aed')}>Publish Blank Quiz</button>
          </form>
        </div>

        {/* 🟢 පැනලය 03: සතිපතා / මාසික නිවේදන සහ සිසුන්ගේ ගැටලු */}
        <div style={styles.card('#ea580c')}>
          <h3 style={styles.cardTitle}>📢 නිවේදන සහ සිසුන්ගේ ප්‍රශ්න (Notice Board)</h3>
          <p style={styles.cardDesc}>සතිපතා ඉලක්ක, මාසික පන්ති නිවේදන හෝ ළමයින් අහපු ප්‍රශ්න වලට උත්තර මෙතනින් දාන්න.</p>
          <form onSubmit={handleNoticeSubmit} style={styles.formGap}>
            <select value={noticeGrade} onChange={e => setNoticeGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={noticeType} onChange={e => setNoticeType(e.target.value)} style={styles.inputStyle}>
              <option value="Weekly Target">🎯 සතිපතා ඉලක්කය (Weekly Target)</option>
              <option value="Monthly Notice">📅 මාසික නිවේදනය (Monthly Notice)</option>
              <option value="Student Q&A Help">💬 සිසුන්ගේ ගැටලුවලට පිළිතුරු (Q&A Solution)</option>
            </select>
            <textarea placeholder="ලියාපදිංචි සිසුන් සඳහා වන නිවේදනය හෝ පණිවිඩය මෙතන ටයිප් කරන්න..." value={noticeContent} onChange={e => setNoticeContent(e.target.value)} required style={styles.textareaStyle} />
            <button type="submit" style={styles.btnStyle('#ea580c')}>Post to Notice Board</button>
          </form>
        </div>

      </div>
    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column' }),
  cardTitle: { margin: '0 0 5px 0', fontSize: '16.5px', color: '#1e293b', fontWeight: 'bold' },
  cardDesc: { margin: '0 0 15px 0', fontSize: '13px', color: '#64748b', lineHeight: '1.4' },
  formGap: { display: 'flex', flexDirection: 'column', gap: '12px' },
  inputStyle: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box' },
  textareaStyle: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box', height: '75px', resize: 'none' },
  btnStyle: (color) => ({ width: '100%', padding: '11px', backgroundColor: color, color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13.5px', marginTop: '5px' })
};
